CREATE TYPE "AccountStatus" AS ENUM ('ACTIVE','SUSPENDED','BANNED','DELETED');
CREATE TYPE "SceneVisibility" AS ENUM ('PUBLIC','PRIVATE','PAID','UNLISTED');
CREATE TYPE "MembershipStatus" AS ENUM ('PENDING','ACTIVE','CANCELLED','EXPIRED','PAST_DUE');
CREATE TYPE "CommunityRole" AS ENUM ('FOUNDER','CO_FOUNDER','CURATOR','MODERATOR','HOST','MEMBER');

CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"emailVerifiedAt" TIMESTAMP(3),"passwordHash" TEXT NOT NULL,"username" TEXT NOT NULL UNIQUE,"displayName" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"status" "AccountStatus" NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE "UserProfile" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL UNIQUE REFERENCES "User"("id") ON DELETE CASCADE,"bio" VARCHAR(280),"avatarUrl" TEXT,"coverUrl" TEXT,"identityIconId" TEXT,"clubId" TEXT NOT NULL UNIQUE,"rankId" TEXT,"reputationXp" INTEGER NOT NULL DEFAULT 0,"memberSince" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"isDiscoverable" BOOLEAN NOT NULL DEFAULT true,"showMembership" BOOLEAN NOT NULL DEFAULT true,"showScenes" BOOLEAN NOT NULL DEFAULT true,"showSquads" BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE "AgeAssuranceRecord" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL UNIQUE REFERENCES "User"("id") ON DELETE CASCADE,"declaredAdult" BOOLEAN NOT NULL,"method" TEXT NOT NULL DEFAULT 'SELF_DECLARATION',"confirmedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"policyVersion" TEXT NOT NULL);
CREATE TABLE "UserInterest" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"interest" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("userId","interest"));
CREATE TABLE "TermsAcceptance" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"termsVersion" TEXT NOT NULL,"privacyVersion" TEXT NOT NULL,"communityGuidelinesVersion" TEXT NOT NULL,"acceptedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"ipHash" TEXT);
CREATE TABLE "EmailVerificationToken" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"tokenHash" TEXT NOT NULL UNIQUE,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "PasswordResetToken" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"tokenHash" TEXT NOT NULL UNIQUE,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "UserSession" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"sessionToken" TEXT NOT NULL UNIQUE,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"revokedAt" TIMESTAMP(3),"ipHash" TEXT,"userAgent" TEXT);
CREATE TABLE "Scene" ("id" TEXT PRIMARY KEY,"founderId" TEXT NOT NULL REFERENCES "User"("id"),"name" TEXT NOT NULL,"slug" TEXT NOT NULL UNIQUE,"description" TEXT NOT NULL,"category" TEXT NOT NULL,"coverUrl" TEXT,"iconId" TEXT,"visibility" "SceneVisibility" NOT NULL DEFAULT 'PUBLIC',"accessPriceKobo" BIGINT,"rules" JSONB NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "SceneMember" ("id" TEXT PRIMARY KEY,"sceneId" TEXT NOT NULL REFERENCES "Scene"("id") ON DELETE CASCADE,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"role" "CommunityRole" NOT NULL DEFAULT 'MEMBER',"status" "MembershipStatus" NOT NULL DEFAULT 'ACTIVE',"joinedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("sceneId","userId"));
CREATE TABLE "SceneChannel" ("id" TEXT PRIMARY KEY,"sceneId" TEXT NOT NULL REFERENCES "Scene"("id") ON DELETE CASCADE,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"description" TEXT,"isDefault" BOOLEAN NOT NULL DEFAULT false,"archivedAt" TIMESTAMP(3),UNIQUE("sceneId","slug"));
CREATE TABLE "Squad" ("id" TEXT PRIMARY KEY,"founderId" TEXT NOT NULL REFERENCES "User"("id"),"name" TEXT NOT NULL,"slug" TEXT NOT NULL UNIQUE,"description" TEXT NOT NULL,"iconId" TEXT,"coverUrl" TEXT,"isDiscoverable" BOOLEAN NOT NULL DEFAULT false,"parentSceneId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "SquadMember" ("id" TEXT PRIMARY KEY,"squadId" TEXT NOT NULL REFERENCES "Squad"("id") ON DELETE CASCADE,"userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"role" "CommunityRole" NOT NULL DEFAULT 'MEMBER',"joinedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("squadId","userId"));

CREATE INDEX "User_createdAt_idx" ON "User"("createdAt");
CREATE INDEX "User_status_createdAt_idx" ON "User"("status","createdAt");
CREATE INDEX "UserInterest_interest_idx" ON "UserInterest"("interest");
CREATE INDEX "Scene_visibility_category_active_idx" ON "Scene"("visibility","category","active");
CREATE INDEX "Scene_founderId_createdAt_idx" ON "Scene"("founderId","createdAt");
CREATE INDEX "SceneMember_userId_status_idx" ON "SceneMember"("userId","status");
CREATE INDEX "Squad_parentSceneId_isDiscoverable_idx" ON "Squad"("parentSceneId","isDiscoverable");
CREATE INDEX "SquadMember_userId_joinedAt_idx" ON "SquadMember"("userId","joinedAt");
CREATE INDEX "UserSession_userId_expiresAt_idx" ON "UserSession"("userId","expiresAt");
CREATE INDEX "EmailVerificationToken_userId_expiresAt_idx" ON "EmailVerificationToken"("userId","expiresAt");
CREATE INDEX "PasswordResetToken_userId_expiresAt_idx" ON "PasswordResetToken"("userId","expiresAt");